import { NextResponse } from "next/server";
import { z } from "zod";
import { createServerSupabase } from "@/lib/supabase/server";
const schema=z.object({fullName:z.string().trim().min(2).max(80),contactEmail:z.union([z.string().email().max(254),z.literal("")])});
export async function PATCH(request:Request){try{const supabase=await createServerSupabase();const {data:{user}}=await supabase.auth.getUser();if(!user)return NextResponse.json({error:"Please log in."},{status:401});const {data:profile}=await supabase.from("profiles").select("role").eq("id",user.id).maybeSingle();if(profile?.role!=="vendor")return NextResponse.json({error:"Vendor access is required."},{status:403});const parsed=schema.safeParse(await request.json());if(!parsed.success)return NextResponse.json({error:"Enter a valid name and email address."},{status:400});const {error}=await supabase.from("profiles").update({full_name:parsed.data.fullName,contact_email:parsed.data.contactEmail||null}).eq("id",user.id);if(error)return NextResponse.json({error:"Your profile could not be saved."},{status:400});return NextResponse.json({success:true});}catch{return NextResponse.json({error:"Your profile could not be saved."},{status:503});}}
